import json
import os
import re
import shutil
import zipfile

from lxml import etree

JSON_PATH = "/root/training_feedback.json"
TEMPLATE_HWPX_PATH = "/root/training_feedback_template.hwpx"
OUTPUT_HWPX_PATH = "/root/training_feedback_ready.hwpx"

WORK_DIR = "/tmp/hwpx_work"
EXTRACT_DIR = os.path.join(WORK_DIR, "filled_extracted")


def digits_only(value) -> str:
    if value is None:
        return ""
    if isinstance(value, (int, float)):
        # 참석자수는 정수 의미이므로 소수점 제거
        if isinstance(value, float) and value.is_integer():
            value = int(value)
        return re.sub(r"\D+", "", str(value))
    return re.sub(r"\D+", "", str(value))


def format_satisfaction(value) -> str:
    """만족도: "X.X점 (5.0점 만점)" 형태로 변환."""
    if value is None:
        score_str = ""
    else:
        s = str(value).strip()
        # 예: "4.5/5.0" -> "4.5"
        if "/" in s:
            s = s.split("/", 1)[0].strip()
        # 숫자만 추출 (4, 4.5, 4.50 등)
        m = re.search(r"\d+(?:\.\d+)?", s)
        score_str = m.group(0) if m else s

    return f"{score_str}점 (5.0점 만점)"


def build_replacements(data: dict) -> dict:
    repl = {}
    for k, v in data.items():
        repl[k] = "" if v is None else str(v)

    # Special formatting rules
    if "참석자수" in repl:
        repl["참석자수"] = digits_only(data.get("참석자수"))

    if "만족도" in repl:
        repl["만족도"] = format_satisfaction(data.get("만족도"))

    # Overall opinion field
    if "종합의견" in repl:
        base = repl["종합의견"].rstrip()
        repl["종합의견"] = f"{base} 후속 심화반 검토 요망."

    return repl


def qn_local(el) -> str:
    return etree.QName(el).localname


def remove_layout_caches(paragraph_el) -> int:
    """Remove stale layout-cache elements under a modified <hp:p>."""
    removed = 0
    # Remove any descendant whose local name contains 'lineseg' or 'cache'
    to_remove = []
    for el in paragraph_el.iter():
        if el is paragraph_el:
            continue
        ln = qn_local(el).lower()
        if "lineseg" in ln or "cache" in ln:
            to_remove.append(el)

    for el in to_remove:
        parent = el.getparent()
        if parent is not None:
            parent.remove(el)
            removed += 1

    return removed


PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def replace_in_paragraph(p_el, replacements: dict) -> bool:
    """Replace placeholders within a paragraph.

    Robust to placeholders spanning multiple <hp:t> nodes by concatenating
    all <hp:t> text, replacing in the concatenated string, then placing the
    final text into the first <hp:t> and clearing the rest.

    Returns True if paragraph content changed.
    """
    t_nodes = list(p_el.findall(".//{*}t"))
    if not t_nodes:
        return False

    original = "".join([t.text or "" for t in t_nodes])
    if "{{" not in original:
        return False

    def sub_fn(m):
        key = m.group(1)
        if key not in replacements:
            raise ValueError(f"No replacement provided for placeholder '{{{{{key}}}}}'")
        return replacements[key]

    replaced = PLACEHOLDER_RE.sub(sub_fn, original)

    if replaced == original:
        return False

    # Preserve formatting by keeping first <hp:t> node and clearing the rest.
    t_nodes[0].text = replaced
    for t in t_nodes[1:]:
        t.text = ""

    return True


def process_xml_file(xml_path: str, replacements: dict) -> None:
    parser = etree.XMLParser(remove_blank_text=False)
    tree = etree.parse(xml_path, parser)
    root = tree.getroot()

    modified_paras = 0
    removed_caches_total = 0

    for p_el in root.findall(".//{*}p"):
        try:
            changed = replace_in_paragraph(p_el, replacements)
        except ValueError as e:
            # Bubble up with file context
            raise ValueError(f"{xml_path}: {e}")

        if changed:
            modified_paras += 1
            removed_caches_total += remove_layout_caches(p_el)

    # Write back
    tree.write(xml_path, encoding="utf-8", xml_declaration=True)


def extract_hwpx_to_dir(hwpx_path: str, out_dir: str) -> None:
    shutil.rmtree(out_dir, ignore_errors=True)
    os.makedirs(out_dir, exist_ok=True)
    with zipfile.ZipFile(hwpx_path, "r") as z:
        z.extractall(out_dir)


def repack_dir_to_hwpx(src_dir: str, out_hwpx_path: str) -> None:
    # Preserve directory structure; if 'mimetype' exists, store first and uncompressed.
    all_files = []
    for root, dirs, files in os.walk(src_dir):
        dirs.sort()
        files.sort()
        for fn in files:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, src_dir).replace(os.sep, "/")
            all_files.append((rel, full))

    # Order: mimetype first (if present), then others.
    mimetype = [x for x in all_files if x[0] == "mimetype"]
    others = [x for x in all_files if x[0] != "mimetype"]
    ordered = mimetype + others

    with zipfile.ZipFile(out_hwpx_path, "w") as z:
        for rel, full in ordered:
            if rel == "mimetype":
                z.write(full, rel, compress_type=zipfile.ZIP_STORED)
            else:
                z.write(full, rel, compress_type=zipfile.ZIP_DEFLATED)


def validate_no_placeholders(src_dir: str) -> None:
    bad = []
    for root, dirs, files in os.walk(src_dir):
        for fn in files:
            if not fn.lower().endswith(".xml"):
                continue
            p = os.path.join(root, fn)
            with open(p, "r", encoding="utf-8") as f:
                s = f.read()
            if "{{" in s or "}}" in s:
                bad.append(p)

    if bad:
        msg = "\n".join(bad)
        raise RuntimeError(f"Placeholders still remain in XML files:\n{msg}")


def main():
    # 1. Load JSON
    with open(JSON_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)

    # 2. Build replacement map
    replacements = build_replacements(data)

    # 3. Extract template
    extract_hwpx_to_dir(TEMPLATE_HWPX_PATH, EXTRACT_DIR)

    # 4. Process XML files
    for root, dirs, files in os.walk(EXTRACT_DIR):
        for fn in files:
            if fn.lower().endswith(".xml"):
                process_xml_file(os.path.join(root, fn), replacements)

    # 5. Validate placeholders removed
    validate_no_placeholders(EXTRACT_DIR)

    # 6. Repack
    repack_dir_to_hwpx(EXTRACT_DIR, OUTPUT_HWPX_PATH)

    print(f"Wrote: {OUTPUT_HWPX_PATH}")


if __name__ == "__main__":
    main()

